import React, { useEffect, useState } from "react";
import postService from "../../services/postService";

export default function PostManagement() {
  const [posts, setPosts] = useState([]);
  const [form, setForm] = useState({ title: "", slug: "", summary: "", content: "", thumbnail: "", status: "DRAFT" });
  const [editingId, setEditingId] = useState(null);

  const loadPosts = () => {
    postService.getAllAdmin().then((res) => setPosts(res.data));
  };

  useEffect(() => { loadPosts(); }, []);

  const handleSubmit = (e) => {
    e.preventDefault();
    if (editingId) {
      postService.update(editingId, form).then(() => {
        alert("Cập nhật bài viết thành công!");
        resetForm();
        loadPosts();
      });
    } else {
      postService.create(form).then(() => {
        alert("Tạo bài viết mới thành công!");
        resetForm();
        loadPosts();
      });
    }
  };

  const handleEdit = (p) => {
    setEditingId(p.id);
    setForm({ title: p.title, slug: p.slug, summary: p.summary, content: p.content, thumbnail: p.thumbnail, status: p.status });
  };

  const handleDelete = (id) => {
    if (window.confirm("Bạn chắc chắn muốn xóa bài viết này không?")) {
      postService.delete(id).then(() => {
        alert("Đã xóa bài viết!");
        loadPosts();
      });
    }
  };

  const resetForm = () => {
    setEditingId(null);
    setForm({ title: "", slug: "", summary: "", content: "", thumbnail: "", status: "DRAFT" });
  };

  return (
    <div className="p-6 sm:p-8 max-w-7xl mx-auto">
      <h1 className="text-3xl font-black text-slate-800 mb-8 tracking-tight">HỆ THỐNG QUẢN TRỊ BÀI VIẾT</h1>

      {/* Editor Form */}
      <form onSubmit={handleSubmit} className="bg-white p-6 rounded-2xl shadow-sm border border-slate-100 mb-10 space-y-4">
        <h2 className="text-lg font-black text-slate-700 border-b pb-2">{editingId ? "📝 CẬP NHẬT BÀI VIẾT" : "✨ SOẠN THẢO BÀI VIẾT MỚI"}</h2>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-xs font-bold text-slate-600 mb-1">Tiêu đề bài viết</label>
            <input type="text" value={form.title} onChange={(e) => setForm({ ...form, title: e.target.value })} className="w-full border rounded-xl p-2 text-sm focus:outline-none focus:border-blue-500" required />
          </div>
          <div>
            <label className="block text-xs font-bold text-slate-600 mb-1">Đường dẫn tĩnh (Slug - tùy chọn)</label>
            <input type="text" value={form.slug} onChange={(e) => setForm({ ...form, slug: e.target.value })} placeholder="dạng: xe-dap-dep" className="w-full border rounded-xl p-2 text-sm focus:outline-none" />
          </div>
        </div>
        <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
          <div>
            <label className="block text-xs font-bold text-slate-600 mb-1">URL Ảnh đại diện (Thumbnail)</label>
            <input type="text" value={form.thumbnail} onChange={(e) => setForm({ ...form, thumbnail: e.target.value })} placeholder="https://..." className="w-full border rounded-xl p-2 text-sm focus:outline-none" />
          </div>
          <div>
            <label className="block text-xs font-bold text-slate-600 mb-1">Trạng thái xuất bản</label>
            <select value={form.status} onChange={(e) => setForm({ ...form, status: e.target.value })} className="w-full border rounded-xl p-2 text-sm font-semibold focus:outline-none">
              <option value="DRAFT">Bản nháp (DRAFT)</option>
              <option value="PUBLISHED">Công khai (PUBLISHED)</option>
              <option value="ARCHIVED">Lưu trữ/Ẩn (ARCHIVED)</option>
            </select>
          </div>
        </div>
        <div>
          <label className="block text-xs font-bold text-slate-600 mb-1">Tóm tắt ngắn (Summary)</label>
          <textarea value={form.summary} onChange={(e) => setForm({ ...form, summary: e.target.value })} rows="2" className="w-full border rounded-xl p-2 text-sm focus:outline-none" required></textarea>
        </div>
        <div>
          <label className="block text-xs font-bold text-slate-600 mb-1">Nội dung chi tiết bài viết (Hỗ trợ định dạng HTML)</label>
          <textarea value={form.content} onChange={(e) => setForm({ ...form, content: e.target.value })} rows="6" placeholder="<p>Nội dung bài viết...</p>" className="w-full border rounded-xl p-2 text-sm font-mono focus:outline-none" required></textarea>
        </div>
        <div className="flex gap-2 justify-end pt-2">
          {editingId && <button type="button" onClick={resetForm} className="bg-slate-100 text-slate-600 font-bold px-4 py-2 rounded-xl text-sm hover:bg-slate-200">Hủy sửa</button>}
          <button type="submit" className="bg-blue-600 text-white font-bold px-6 py-2 rounded-xl text-sm hover:bg-blue-700 shadow-md transition">{editingId ? "Cập nhật bài" : "Đăng bài viết"}</button>
        </div>
      </form>

      {/* List Table Data */}
      <div className="bg-white rounded-2xl shadow-sm border border-slate-100 overflow-hidden">
        <table className="w-full text-left border-collapse">
          <thead>
            <tr className="bg-slate-800 text-white text-xs uppercase tracking-wider font-bold">
              <th className="p-4">ID</th>
              <th className="p-4">Ảnh</th>
              <th className="p-4">Tiêu đề bài viết</th>
              <th className="p-4">Người viết</th>
              <th className="p-4">Trạng thái</th>
              <th className="p-4 text-center">Hành động</th>
            </tr>
          </thead>
          <tbody className="divide-y text-sm font-medium text-slate-700">
            {posts.map((p) => (
              <tr key={p.id} className="hover:bg-slate-50/80 transition">
                <td className="p-4 font-bold text-slate-400">#{p.id}</td>
                <td className="p-4">
                  <img src={p.thumbnail || "https://placehold.co/50x50"} alt="" className="w-10 h-10 object-cover rounded-lg border shadow-sm" />
                </td>
                <td className="p-4 font-bold text-slate-900 max-w-xs truncate">{p.title}</td>
                <td className="p-4 text-xs">{p.authorName}</td>
                <td className="p-4">
                  <span className={`px-2.5 py-1 rounded-full text-[11px] font-bold ${p.status === "PUBLISHED" ? "bg-green-50 text-green-700" : p.status === "DRAFT" ? "bg-amber-50 text-amber-700" : "bg-slate-100 text-slate-700"}`}>{p.status}</span>
                </td>
                <td className="p-4 flex justify-center gap-2">
                  <button onClick={() => handleEdit(p)} className="text-blue-600 hover:bg-blue-50 px-2.5 py-1 rounded-lg text-xs font-bold transition">Sửa</button>
                  <button onClick={() => handleDelete(p.id)} className="text-rose-600 hover:bg-rose-50 px-2.5 py-1 rounded-lg text-xs font-bold transition">Xóa</button>
                </td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}
